    query: Option<String>,
    threshold: f32,
) -> Result<Vec<ScrapedPage>> {
    if let Some(ref q) = query {
        // Validate query length
        const MAX_QUERY_LENGTH: usize = 1000;
        if q.len() > MAX_QUERY_LENGTH {
            anyhow::bail!(
                "Query too long ({} characters, maximum {})",
                q.len(),
                MAX_QUERY_LENGTH
            );
        }

        let (kept_pages, filtered_count) = scrape::filter_pages_by_relevance(
            pages,
            q,
            threshold,
        );

        if kept_pages.is_empty() {
            anyhow::bail!(
                "All {} pages filtered out by query '{}' (threshold: {})",
                filtered_count,
                q,
                threshold
            );
        }

        println!("  Filtered by relevance: {} pages removed", filtered_count);
        Ok(kept_pages)
    } else {
        Ok(pages)
    }
}

